if (element.querySelector('.quick-settings-toolbar')) return;

var toolbar = document.createElement('div');
toolbar.className = 'quick-settings-toolbar';
toolbar.setAttribute('data-qs-toolbar', 'true');

toolbar.innerHTML = 
'<style>' +
'.quick-settings-toolbar {' +
'  position: sticky;' +
'  top: 0; z-index: 10001;' +
'  display: flex; align-items: center; gap: 18px;' +
'  padding: 6px 16px;' +
'  background: #2d2d3f; color: #e0e0e0;' +
'  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;' +
'  font-size: 12px; border-bottom: 2px solid #fa005a;' +
'  box-shadow: 0 2px 8px rgba(0,0,0,0.3);' +
'  flex-wrap: wrap;' +
'}' +
'.quick-settings-toolbar .qs-group {' +
'  display: flex; align-items: center; gap: 6px;' +
'}' +
'.quick-settings-toolbar label {' +
'  white-space: nowrap; font-weight: 600; letter-spacing: 0.3px;' +
'}' +
'.quick-settings-toolbar input[type="range"] {' +
'  width: 100px; cursor: pointer; accent-color: #fa005a;' +
'}' +
'.quick-settings-toolbar .qs-toggle-btn {' +
'  display: flex; align-items: center; gap: 6px;' +
'  padding: 4px 12px; border-radius: 16px;' +
'  background: #4a4a5e; border: 1px solid #6a6a7e;' +
'  color: #e0e0e0; cursor: pointer; font-size: 12px; font-weight: 600;' +
'  transition: all 0.2s ease;' +
'}' +
'.quick-settings-toolbar .qs-toggle-btn:hover {' +
'  background: #5a5a70; border-color: #fa005a;' +
'}' +
'.quick-settings-toolbar .qs-toggle-btn.active {' +
'  background: #fa005a; border-color: #fa005a; color: #fff;' +
'}' +
'.quick-settings-toolbar .qs-value {' +
'  min-width: 28px; text-align: center; font-variant-numeric: tabular-nums; opacity: 0.8;' +
'}' +
'</style>' +
'<div class="qs-group">' +
'  <label for="qs-font-size">&#9000; Font Size:</label>' +
'  <input type="range" id="qs-font-size" min="12" max="24" step="1" value="15">' +
'  <span class="qs-value" id="qs-font-size-val">15px</span>' +
'</div>' +
'<div class="qs-group">' +
'  <label for="qs-layout-width">&#8962; Layout Width:</label>' +
'  <input type="range" id="qs-layout-width" min="60" max="100" step="5" value="80">' +
'  <span class="qs-value" id="qs-layout-width-val">80%</span>' +
'</div>' +
'<div class="qs-group">' +
'  <button class="qs-toggle-btn" id="qs-dark-mode" title="Toggle Dark Mode">&#9790; Dark Mode</button>' +
'</div>';

element.insertBefore(toolbar, element.firstChild);

var fontSizeSlider = document.getElementById('qs-font-size');
var fontSizeVal = document.getElementById('qs-font-size-val');
var layoutWidthSlider = document.getElementById('qs-layout-width');
var layoutWidthVal = document.getElementById('qs-layout-width-val');
var darkModeBtn = document.getElementById('qs-dark-mode');

var savedFontSize = localStorage.getItem('qs-font-size');
var savedLayoutWidth = localStorage.getItem('qs-layout-width');
var savedDarkMode = localStorage.getItem('qs-dark-mode');

if (savedFontSize) {
  fontSizeSlider.value = savedFontSize;
  document.body.style.fontSize = savedFontSize + 'px';
  fontSizeVal.textContent = savedFontSize + 'px';
}
if (savedLayoutWidth) {
  layoutWidthSlider.value = savedLayoutWidth;
  var mainContent = document.querySelector('.page') || document.querySelector('.main-container');
  if (mainContent) {
    mainContent.style.maxWidth = savedLayoutWidth + '%';
    mainContent.style.marginLeft = 'auto';
    mainContent.style.marginRight = 'auto';
  }
  layoutWidthVal.textContent = savedLayoutWidth + '%';
}
if (savedDarkMode === 'true') {
  document.body.setAttribute('data-theme', 'dark');
  document.body.classList.add('theme-fandomdesktop-dark');
  document.body.classList.remove('theme-fandomdesktop-light');
  darkModeBtn.classList.add('active');
  darkModeBtn.innerHTML = '&#9728; Light Mode';
}

fontSizeSlider.addEventListener('input', function() {
  var val = this.value;
  document.body.style.fontSize = val + 'px';
  fontSizeVal.textContent = val + 'px';
  localStorage.setItem('qs-font-size', val);
});

layoutWidthSlider.addEventListener('input', function() {
  var val = this.value;
  var mainContent = document.querySelector('.page') || document.querySelector('.main-container');
  if (mainContent) {
    mainContent.style.maxWidth = val + '%';
    mainContent.style.marginLeft = 'auto';
    mainContent.style.marginRight = 'auto';
  }
  layoutWidthVal.textContent = val + '%';
  localStorage.setItem('qs-layout-width', val);
});

darkModeBtn.addEventListener('click', function() {
  var isDark = document.body.getAttribute('data-theme') === 'dark';
  if (isDark) {
    document.body.setAttribute('data-theme', 'light');
    document.body.classList.add('theme-fandomdesktop-light');
    document.body.classList.remove('theme-fandomdesktop-dark');
    this.classList.remove('active');
    this.innerHTML = '&#9790; Dark Mode';
    localStorage.setItem('qs-dark-mode', 'false');
  } else {
    document.body.setAttribute('data-theme', 'dark');
    document.body.classList.add('theme-fandomdesktop-dark');
    document.body.classList.remove('theme-fandomdesktop-light');
    this.classList.add('active');
    this.innerHTML = '&#9728; Light Mode';
    localStorage.setItem('qs-dark-mode', 'true');
  }
});
